# 64x_career_orientation_rolling.R
#
# PJ, 11 Sep: the annual career-orientation series (64u/64v/64w) is real but
# too thin year-to-year to read (individual years driven by single-digit
# raw hit counts, e.g. 2025 frontbench = 2 hits). Option 2 from the choice
# offered: smooth with a rolling multi-year window rather than plot annual
# noise or abandon the series.
#
# METHOD: 5-year centred window (t-2..t+2, shorter at the ends), SUM raw
# hits across the window before taking the ratio - not a rolling mean of
# already-noisy annual ratios, for the same reason the annual series itself
# had to move from per-speech-ratio-averaging to aggregate-then-ratio (see
# 64u's header). Summing counts first is the only version of "smoothing"
# that actually pools the sparse signal rather than averaging noise.
#
# INPUT: online_appendix/ch3_career_orientation_full_1979_2025.csv (64w)
# OUTPUT: online_appendix/ch3_career_orientation_rolling5yr_1979_2025.csv

suppressMessages({library(dplyr); library(readr)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT   <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
OUT_DIR   <- file.path(WKBD_ROOT, "online_appendix")

d <- read_csv(file.path(OUT_DIR, "ch3_career_orientation_full_1979_2025.csv"), show_col_types = FALSE) |>
  arrange(year)

WINDOW <- 2  # +/- 2 years = 5-year centred window

roll_ratio <- function(years, career_sum, policy_sum, y0, window) {
  idx <- which(years >= y0 - window & years <= y0 + window)
  cs <- sum(career_sum[idx]); ps <- sum(policy_sum[idx])
  (cs + 0.5) / (cs + ps + 1)
}
roll_n <- function(years, career_sum, y0, window) {
  idx <- which(years >= y0 - window & years <= y0 + window)
  sum(career_sum[idx])
}

d <- d |>
  rowwise() |>
  mutate(
    backbench_ratio_5yr  = roll_ratio(d$year, d$backbench_n_career_sum, d$backbench_n_policy_sum, year, WINDOW),
    frontbench_ratio_5yr = roll_ratio(d$year, d$frontbench_n_career_sum, d$frontbench_n_policy_sum, year, WINDOW),
    backbench_hits_5yr   = roll_n(d$year, d$backbench_n_career_sum, year, WINDOW),
    frontbench_hits_5yr  = roll_n(d$year, d$frontbench_n_career_sum, year, WINDOW)
  ) |>
  ungroup()

cat("=== 5-year rolling career-orientation series ===\n")
print(as.data.frame(d |>
  mutate(across(c(backbench_ratio_5yr, frontbench_ratio_5yr), ~round(.*100, 2))) |>
  select(year, backbench_ratio_5yr, frontbench_ratio_5yr, backbench_hits_5yr, frontbench_hits_5yr)),
  row.names = FALSE)

period <- function(dd, y0, y1, col) dd |> filter(year >= y0, year <= y1) |> summarise(m = mean({{col}}, na.rm = TRUE)) |> pull(m)
cat("\n=== PERIOD MEANS OF THE 5-YEAR-SMOOTHED SERIES (sanity check vs raw annual period means) ===\n")
for (rng in list(c(1979,1988), c(1989,1997), c(1998,2009), c(2010,2019), c(2020,2025))) {
  bb <- period(d, rng[1], rng[2], backbench_ratio_5yr)
  fb <- period(d, rng[1], rng[2], frontbench_ratio_5yr)
  cat(sprintf("%d-%d: Backbench %.2f%%  |  Frontbench %.2f%%  |  Frontbench premium %+.2fpp\n",
              rng[1], rng[2], bb*100, fb*100, (fb-bb)*100))
}

cat("\n=== Min raw hit count feeding any single smoothed point (data-thinness check) ===\n")
cat("Backbench: min =", min(d$backbench_hits_5yr), " | Frontbench: min =", min(d$frontbench_hits_5yr), "\n")

OUT <- file.path(OUT_DIR, "ch3_career_orientation_rolling5yr_1979_2025.csv")
write_csv(d, OUT)
cat("\nSaved:", OUT, "\n")
